import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"乾","description":"焦氏易林注 - 乾","frontmatter":{"title":"乾","description":"焦氏易林注 - 乾"},"headers":[],"relativePath":"zh/classics/jiaoyilin/001.md","filePath":"zh/classics/jiaoyilin/001.md"}'),l={name:"zh/classics/jiaoyilin/001.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="乾" tabindex="-1">乾 <a class="header-anchor" href="#乾" aria-label="Permalink to “乾”">​</a></h1><h3 id="乾-1" tabindex="-1">乾 <a class="header-anchor" href="#乾-1" aria-label="Permalink to “乾”">​</a></h3><h3 id="乾之乾" tabindex="-1">乾之乾 <a class="header-anchor" href="#乾之乾" aria-label="Permalink to “乾之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>道陟石阪，胡言連謇。譯喑且聾，莫使道通。請謁不行，求事無功。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>乾為道、為陟、為山，故曰石阪。為言，在西北，故曰胡言。連謇，口吃也。震為鳴，坎為耳，艮為道、為請求，今為純乾，乾三子具不見，故曰暗、曰聾、曰道不通、曰請求無功，蓋三子各分乾一爻也。又林詞所以不吉者，以卦為純陽，陽遇陽則窒故也。此易之根本大義，自此義不明而易多誤解。○石，汲古作多，謇作蹇，喑訛瘠。依宋元本。</p><h3 id="乾之坤" tabindex="-1">乾之坤 <a class="header-anchor" href="#乾之坤" aria-label="Permalink to “乾之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>招殃來螫，害我邦國。病傷手足，不得安息。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>乾變陰故曰招。日來坤陰為災殃、為毒螫、為害、為邦國。艮手震足，今純坤艮震毀，故曰病傷手足。坤逆行故曰來，《繫辭》「來者，伸也。」即謂坤逆行。○殃，元本作禍，依宋本、汲古。傷，宋元本作在，依汲古。</p><h3 id="乾之屯" tabindex="-1">乾之屯 <a class="header-anchor" href="#乾之屯" aria-label="Permalink to “乾之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>陽孤亢極，多所恨惑。車傾蓋亡，身常憂惶。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>乃得其願，雌雄相從。坎為孤，一陽居五，民皆歸初，故曰孤亢。坎為憂疑，故曰恨惑、曰憂惶。艮為蓋，震為車。坎破，故傾亡。坤為身，初陽四陰、二陰五陽皆有應與，故曰雌雄相從。○凡六子易林皆有孤、獨、鰥、寡象，人皆知巽寡，餘失傳。不下贅。</p><h3 id="乾之蒙" tabindex="-1">乾之蒙 <a class="header-anchor" href="#乾之蒙" aria-label="Permalink to “乾之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>鴶鵴鳲鳩，專一無尤。君子是則，長受嘉福。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>艮為鳥，故曰鴶鵴鳲鳩。艮止，故專。一說鳲鳩義與毛同。艮為君子，坎為法則，震為嘉福。○艮，鳥象，失傳。鴶，音戞。鴶鵴鳴鳩，皆布穀也。鴶，各本多訛鵠，依宋元本。</p><h3 id="乾之需" tabindex="-1">乾之需 <a class="header-anchor" href="#乾之需" aria-label="Permalink to “乾之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>目瞤足動，喜如其願，舉家蒙寵。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>互離為目。瞤，亦動也。乾為喜、為寵。坎為官室、為家。《西京雜記》「目瞤得酒食，故曰喜。」足，疑為指訛，《左傳》「食指動」是也，伏艮象。○目，汲古訛日，從宋元本。</p><h3 id="乾之訟" tabindex="-1">乾之訟 <a class="header-anchor" href="#乾之訟" aria-label="Permalink to “乾之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>龍馬上山，絕無水泉。喉焦唇乾，舌不能言。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>乾為龍馬、為山，在上，坎在下而中為火、為日，故水泉絕。兌為喉舌、為唇，乃兌覆而與火鄰，故焦渴不能言。</p><h3 id="乾之師" tabindex="-1">乾之師 <a class="header-anchor" href="#乾之師" aria-label="Permalink to “乾之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>倉盈庾億，宜種黍稷。年豐歲熟，民人安息。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>坤為腹、為囊，倉庾象也。坤眾故曰盈、曰億、曰豐熟。震為黍稷，坤為歲年、為民人、為安息。後比之升、坤之恆詞同，亦皆以坤為倉庾。《詩小雅楚茨》雲「我黍與與，我稷翼翼；我倉既盈，我庾維億。」又《甫田》雲「曾孫之稼，如茨如梁；曾孫之庾，如坁如京。乃求千斯倉，乃求萬斯箱；黍稷稻粱，農夫之慶。」○年豐歲熟，元刊作國家富有；安作蕃，依宋本、汲古。</p><h3 id="乾之比" tabindex="-1">乾之比 <a class="header-anchor" href="#乾之比" aria-label="Permalink to “乾之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>中夜犬吠，盜在牆外。神明佑助，消散皆去。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>坤、坎皆為夜。坎為中，故曰中夜。艮為犬，伏兌口，故曰犬吠。坎為盜，艮為牆，坎在外故曰在牆外。伏乾為神，艮為明，坤消故曰消散。○犬，元刊作狗，依汲古。</p><h3 id="乾之小畜" tabindex="-1">乾之小畜 <a class="header-anchor" href="#乾之小畜" aria-label="Permalink to “乾之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>據鬥運樞，順天無憂，與樂並居。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>通豫。艮為星，數七，故曰據鬥。坎為樞，故曰運樞。乾順行故曰順天。坎伏故無憂。震為樂，艮為居。○汲古多「所行造德」四字，依宋元本。</p><h3 id="乾之履" tabindex="-1">乾之履 <a class="header-anchor" href="#乾之履" aria-label="Permalink to “乾之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>空拳握手，倒地更起。富饒豐衍，快樂無已。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通謙。艮為拳、為手，坤為地，為下。震起，故曰倒地更起。坤為富饒，震為快樂，全用伏象，易卦爻詞每如此也，易林無創例。○倒，汲古作委，依宋元本。</p><h3 id="乾之泰" tabindex="-1">乾之泰 <a class="header-anchor" href="#乾之泰" aria-label="Permalink to “乾之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>不風不雨，白日皎皎。宜出驅馳，通利大道。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>巽伏故不風，半坎故不雨。震為白，乾為日，震為出、為馳驅、為大塗、為通利。○利，汲古作理，從宋本。</p><h3 id="乾之否" tabindex="-1">乾之否 <a class="header-anchor" href="#乾之否" aria-label="Permalink to “乾之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>載日晶光，驂駕六龍。祿命徹天，封為燕王。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>坤為載，乾為日，在上故曰載日。伏震為龍、為駕，乾數六，故曰驂駕六龍。乾為祿，巽為命，乾在上，故曰徹天，伏震為王，兌為燕，故曰燕王。○載，元本作戴，依宋本、汲古。</p><h3 id="乾之同人" tabindex="-1">乾之同人 <a class="header-anchor" href="#乾之同人" aria-label="Permalink to “乾之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>子號索哺，母行求食。反見空巢，訾我長息。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通師。震為子、為號、為哺、為請。請，求也。故曰索哺、曰求食。震為行，坤為母，艮為巢，坤虛，故曰空巢。震為長息，坎上下兩兌口相背，兌為口舌，故曰訾。○巢，依宋元本，汲古作窠。</p><h3 id="乾之大有" tabindex="-1">乾之大有 <a class="header-anchor" href="#乾之大有" aria-label="Permalink to “乾之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>上帝之生，福佑日成。修德行惠，樂且安寧。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>乾為上帝、為福、為德惠。通比，比樂坤安。本象、伏象兼取。○第四句元刊作樂安且寧，依汲古。</p><h3 id="乾之謙" tabindex="-1">乾之謙 <a class="header-anchor" href="#乾之謙" aria-label="Permalink to “乾之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>山險難登，澗中多石。車馳轊擊，載重傷軸。擔負差躓，跌踒右足。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>艮為山、為石，坎為澗，坎險，故難登。震為車，坎多眚，故轊擊傷軸。坎為轊、為軸，艮為何，故曰擔負。坎蹇，故差躓、故跌踒。差，同蹉也。震為足，艮伏兌，故曰右足。○擔，依汲古。元刊作儋，義同。跌踒，汲古作踠跌，依宋元本。</p><h3 id="乾之豫" tabindex="-1">乾之豫 <a class="header-anchor" href="#乾之豫" aria-label="Permalink to “乾之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>禹鑿龍門，通利水源。東註滄海，民得安存。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為帝，故曰禹。艮手，故曰鑿。坤為門，震為龍，故曰龍門。坎水坤水，故曰水源，震為通利、為東，坤為滄海、為民、為安。</p><h3 id="乾之隨" tabindex="-1">乾之隨 <a class="header-anchor" href="#乾之隨" aria-label="Permalink to “乾之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>乘龍上天，兩蛇為輔。踴躍雲中，游觀滄海。民樂安處。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>震為龍，艮為天，故曰乘龍上天。巽蛇，兌卦數二，故曰兩蛇。輔，附也。互大坎為雲，坎在上，震起，故曰踴躍雲中。兌為澤，故曰海，艮為觀、為安。○民樂安處，元刊作安樂長處，依汲古。</p><h3 id="乾之蠱" tabindex="-1">乾之蠱 <a class="header-anchor" href="#乾之蠱" aria-label="Permalink to “乾之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>彭祖九子，據德不殆。南山松柏，長受嘉福。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>艮為壽，故曰彭祖。彭祖名篯，壽八百歲，即《論語》所謂老彭也。震為子，數九，故曰九子。艮為據，震為德，艮山，震南，故曰南山。巽為松柏，震為嘉福。○德，元刊作得。</p><h3 id="乾之臨" tabindex="-1">乾之臨 <a class="header-anchor" href="#乾之臨" aria-label="Permalink to “乾之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>南山昊天，刺政閔身。疾悲無辜，皆憎為仇。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>通遁。艮為南山。乾盈已正當夏日，故曰昊天。本象。坤為政、為身、為悲、為憎，故刺政憫身。艮為背也。南山昊天，皆小雅篇名，皆刺幽王而悲憫身世也。刺政，承南山而言，謂「赫赫師尹，不平謂何」也。閔身，承昊天言，謂若此無罪，熏胥以鋪也。○閔，宋、元刊、汲古皆作關，依局本。</p><h3 id="乾之觀" tabindex="-1">乾之觀 <a class="header-anchor" href="#乾之觀" aria-label="Permalink to “乾之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>江河淮海，天之奧府。眾利所聚，可以饒有。樂我君子，百福是受。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>坤為江河淮海，艮為府，坤伏乾，故曰天府。坤為眾、為利、為聚、為富饒。艮為君子，巽伏震為樂，坤為我也。○元本下多百福是受四字，茲從之宋本，汲古無。</p><h3 id="乾之噬嗑" tabindex="-1">乾之噬嗑 <a class="header-anchor" href="#乾之噬嗑" aria-label="Permalink to “乾之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>堅冰黃鳥，終日悲號。不見白粒，但見藜蒿。數驚鷙鳥，為我心憂。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>坎為堅冰，震為黃，艮為鳥、為終。離為日，故曰終日。坎為悲，震為號、為粒，坎隱故不見。震為藜蒿、為驚。艮為黔啄、為鷙鳥。坎為心憂。《詩小雅》「黃鳥黃鳥，無集於榖，此邦之人，不我肯榖。言旋言歸，復我邦族。」林似說此詩。○第二句各本多作常哀悲愁。白作甘，依解之夬校丁晏雲「楚策『俯啄白粒』是也。」</p><h3 id="乾之賁" tabindex="-1">乾之賁 <a class="header-anchor" href="#乾之賁" aria-label="Permalink to “乾之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>室如懸磬，既危且殆。早見之士，依山谷處。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>艮為室，震為磬，上卦震覆，故曰懸磬。坎險故危殆。震為士、為旦，故曰早見之士。離為見也。艮為山谷，艮止故曰依。○谷處，元本作處谷，依宋本、汲古。</p><h3 id="乾之剝" tabindex="-1">乾之剝 <a class="header-anchor" href="#乾之剝" aria-label="Permalink to “乾之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>大禹戒路，蚩尤除道。周匝萬里，不危不殆。見其所使，無所不在。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>伏乾為王，故曰大禹。艮為路，伏兌為口，故曰大禹戒路，言警備也。坤為惡，故曰蚩尤。艮為道、為手，故曰除道。除，治也。反震為周，坤為萬里，坤安艮止，故不危殆。艮為僮僕，故曰所使，卦為大艮，故無不在。○戒，宋元本作式，依汲古。</p><h3 id="乾之復" tabindex="-1">乾之復 <a class="header-anchor" href="#乾之復" aria-label="Permalink to “乾之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>三人為旅，俱歸北海。入門上堂，拜謁王母，飲勞我酒。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>震為人，數三，故曰三人，坤為海、為北，震為反，故曰俱歸北海。坤為門戶，震往，故曰入、曰上。坤為母，震為王，故曰王母。坤為我、為漿，故亦為酒，震為言，故曰勞。○王母，汲古作主母，依宋元本。上，元刊作升，依宋本、汲古。</p><h3 id="乾之無妄" tabindex="-1">乾之無妄 <a class="header-anchor" href="#乾之無妄" aria-label="Permalink to “乾之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>傳言相誤，非乾徑路。鳴鼓逐狐，不知跡處。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>震為言，艮敗言，故曰誤，艮為徑路、為求。非乾徑路，言非所求之徑路也。震為鼓、為鳴，艮為狐。震為逐、為跡。巽為伏，故無跡。○乾，俗本皆誤於。</p><h3 id="乾之大畜" tabindex="-1">乾之大畜 <a class="header-anchor" href="#乾之大畜" aria-label="Permalink to “乾之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>三羊爭雌，相逐奔馳。終日不食，精氣勞疲。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>兌為羊，震數三，故曰三羊。兌為雌，艮為手，正反兩艮相對，故曰爭雌。震為馳逐，乾為日，兌為食，艮為終，艮止，故終日不食。乾為精氣，爭故勞疲。○羊，汲古作年，雌作妻，依宋元本。</p><h3 id="乾之頤" tabindex="-1">乾之頤 <a class="header-anchor" href="#乾之頤" aria-label="Permalink to “乾之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>純服素裳，載主以興。德義茂生，天下歸仁。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>坤為黑、為裳，震為白，故曰純服素裳。震為主、為載、為興，故曰載主以興。坤為義，震為德、為生，故曰德義茂生。坤為天下，震為歸、為仁，故曰天下歸仁。史記武王載木主，觀兵孟津，八百諸侯來歸，故必素裳。○素，各本皆作黃，載主作戴上，茂作既，均非。茂依比之益校。</p><h3 id="乾之大過" tabindex="-1">乾之大過 <a class="header-anchor" href="#乾之大過" aria-label="Permalink to “乾之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>桀跖並處，人民勞苦。擁兵荷糧，戰於齊魯。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>伏坤為惡，故曰桀。巽為盜，故曰跖。坤為人民、為憂、為勞，故曰勞苦。伏艮為兵、為荷，震為糧，故曰擁兵荷糧。巽齊兌魯，正覆艮相背，艮手，故曰戰。○勞，依元刊。汲古作愁。</p><h3 id="乾之坎" tabindex="-1">乾之坎 <a class="header-anchor" href="#乾之坎" aria-label="Permalink to “乾之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>黃鳥採菉，既嫁不答。念我父兄，思復邦國。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>黃鳥、採菉皆小雅篇名，皆傷怨曠，故曰既嫁不答。震為黃、為菉，艮為鳥、為採，故曰黃鳥採菉。震為嫁、為言，艮止，故曰不答。坎為思念，震為父兄、為復，艮為邦國。○採菉，自明以後本皆誤為來集，茲依宋元本。</p><h3 id="乾之離" tabindex="-1">乾之離 <a class="header-anchor" href="#乾之離" aria-label="Permalink to “乾之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>胎生孚乳，長息成就。充滿帝室，家國昌富。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>通坎。互震為胎、為生，坎為孚，艮為乳，故曰胎生孚乳。震為長息，艮為成，故曰成就。震為帝、為昌，艮為室、為家國，全取旁通象。</p><h3 id="乾之咸" tabindex="-1">乾之咸 <a class="header-anchor" href="#乾之咸" aria-label="Permalink to “乾之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>三人求橘，反得丹穴。女清以富，黃金百鎰。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>互乾為人，艮數三，故曰三人。艮為求，乾為橘，故曰三人求橘。兌為穴，乾為赤，故曰丹穴。巽為女，承乾故富，故為金。伏坤為黃，故曰黃金。乾為百。顧千里曰「清者，人名。《貨殖傳》所謂巴寡婦清也。清家得丹穴。」○丹穴，依宋元本，汲古作大慄。清，依顧校。諸本皆作貴，惟汲古作青，可證顧說是也。</p><h3 id="乾之恒" tabindex="-1">乾之恒 <a class="header-anchor" href="#乾之恒" aria-label="Permalink to “乾之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>東山西嶽，會合俱食。百家送從，以成恩福。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>通益。互艮為山嶽。震東，本卦。兌為西，故曰東山西嶽。坤為會合，震為食，正覆震，故曰俱食。艮為家，震為百、為從、為恩福，艮為成也。</p><h3 id="乾之遯" tabindex="-1">乾之遯 <a class="header-anchor" href="#乾之遯" aria-label="Permalink to “乾之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>眵雞無距，與鵲交鬬。翅折目盲，為鳩所傷。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>巽為雞。《說文》：「目眥傷曰眵」，眥，眼角也。艮離目不全，故曰眵雞。震伏，故無距。艮為鵲、為鬬，震為羽翰。震覆，故翅折。離為目，目眥下裂，故為目盲。艮為鳥、為鳩，巽羸故傷。○眵，依汲古，宋元本作弱，非。</p><h3 id="乾之大壯" tabindex="-1">乾之大壯 <a class="header-anchor" href="#乾之大壯" aria-label="Permalink to “乾之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>卻大牆壞，蠧眾木折。狼虎為政，天降罪罰。高弒望夷，胡亥以斃。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>通觀。巽為卻、為壞、為牆，故曰卻大牆壞。巽為蟲、為木，坤眾，故曰蠧眾，風隕故木折。艮為狼虎，坤為政，故曰狼虎為政。乾為天，坤為罪罰，故曰天降罪罰。艮為宦寺，坤為弒，艮為觀，坤為夷，故曰高弒望夷，言趙高弒胡亥於望夷宮也。坤為胡，居亥，又為斃也。雖人名、地名，無不從象生，本之《易》也。</p><h3 id="乾之晉" tabindex="-1">乾之晉 <a class="header-anchor" href="#乾之晉" aria-label="Permalink to “乾之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>三痴俱走，迷路失道。惑不知歸，反入患口。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>坤為痴，爻數三，故曰三痴。互艮為道路，坤迷，故曰迷路失道。坎為惑，震為歸，陽居四不反初，故曰不知歸。坎為患，四五形兌，故曰患口。○惑，元刊作或，依汲古。</p><h3 id="乾之明夷" tabindex="-1">乾之明夷 <a class="header-anchor" href="#乾之明夷" aria-label="Permalink to “乾之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>弓矢俱張，把彈折弦。丸發不至，道遇害患。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>互坎為弓、為矢，震為張，故曰弓矢俱張。坎為彈，伏巽為弦，坎折，故曰把彈折弦。坎為丸，震為發，坤閉，故不至。震為道塗，坤為患害，故曰道遇患害。</p><h3 id="乾之家人" tabindex="-1">乾之家人 <a class="header-anchor" href="#乾之家人" aria-label="Permalink to “乾之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>三女求夫，伺候山隅，不見覆關，長思憂嘆。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>卦二離、一巽，皆女象，坎為夫，故曰三女求夫。艮為關，卦有兩半艮形，故曰復關；坎伏，故不見。不見覆關，詩衛風語也。艮止，故曰伺候。艮山，故曰山隅。坎為憂思，故曰長思憂嘆。○汲古二三句倒置，依元本。元本憂嘆作嘆憂，失韻，依汲古。</p><h3 id="乾之睽" tabindex="-1">乾之睽 <a class="header-anchor" href="#乾之睽" aria-label="Permalink to “乾之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>陽旱炎炎，傷害禾谷。穡人無食，耕夫嘆息。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>重離故曰旱，震為禾稼，二三四五半震兌毀，故曰傷害禾谷。兌為食，坎失，故無食。震為耕、為夫，兌口，故耕夫嘆息。○《易》家人、睽爻詞往往用半象，故此與家人亦多用半象，下蹇、解、漸、歸妹、既、未濟並同，而既、未濟用半象尤多，全本之《易》。</p><h3 id="乾之蹇" tabindex="-1">乾之蹇 <a class="header-anchor" href="#乾之蹇" aria-label="Permalink to “乾之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>騎㹠逐羊，不見所望。徑涉虎廬，亡羝失羔。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>坎為㹠，伏兌為羊，半震為騎、為逐，故曰騎●逐羊。坎隱故不見，離為望也。艮為徑、為虎、為廬，兌伏，故亡羝失羔。○廬，宋元本作穴，依汲古。</p><h3 id="乾之解" tabindex="-1">乾之解 <a class="header-anchor" href="#乾之解" aria-label="Permalink to “乾之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>暗昧冥語，轉相詿誤。鬼魅所舍，誰知卧處。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>坎為暗昧、為冥，震為言，故曰冥語。坎上下兩兌口相背，故曰詿誤。坎為鬼魅、為舍、為伏，故曰卧。坎伏，故不知。○轉相，依宋元本，諸家皆作相傳，非。</p><h3 id="乾之損" tabindex="-1">乾之損 <a class="header-anchor" href="#乾之損" aria-label="Permalink to “乾之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>姬薑祥淑，二人偶食。論仁義福，以安王室。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>互震為周，故曰姬，伏巽，故曰薑，巽為齊也，震為仁，故曰祥淑。震為人，兌卦數二，故曰二人。兌為食也，震為言，故論仁議福。震為王，艮為室、為安，故曰以安王室。</p><h3 id="乾之益" tabindex="-1">乾之益 <a class="header-anchor" href="#乾之益" aria-label="Permalink to “乾之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>公孫駕驪，載聘東齊。延陵說產，遺季紵衣。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>艮為孫，震為公、為驪、為駕，故曰公孫駕驪。震為東，巽為齊，震為載，故曰載聘東齊。艮山，故曰延陵，震樂震生，故曰悅、曰產。艮為季，坤為衣裳，震為紵，故曰遺季紵衣。《左傳》「吳公子札聘於鄭，見子產如舊相識，與之縞帶。子產獻紵衣焉。」○聘，宋元本作眄，依汲古。</p><h3 id="乾之夬" tabindex="-1">乾之夬 <a class="header-anchor" href="#乾之夬" aria-label="Permalink to “乾之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>孤竹之墟，老婦亡夫。傷於蒺藜，不見少齊。東郭棠薑，武子以亡。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>武子，崔杼也。棠薑，杼妻也。《困》三爻「據於蒺藜入於其宮，不見其妻」，杼占詞也。事見《左傳》襄二十五年。少齊者，《左傳》晉人謂之少齊，言美也。伏剝。坤為寡，中虛，故曰孤竹之墟，坤為墟也。兌為老婦，本大過也。艮為夫，艮伏，故無夫。餘象多未詳。○子，各本多誤氏，茲依丁本。齊，汲古作妻，依宋元本。老，各本皆訛失，依需之剝宋元本校。</p><h3 id="乾之姤" tabindex="-1">乾之姤 <a class="header-anchor" href="#乾之姤" aria-label="Permalink to “乾之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>仁政不暴，鳳凰來舍。四時順節，民安其處。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>通復。震為仁，故曰不暴。坤為文，故曰鳳凰。震為辰，卦數四，坤順，故曰四時順節。坤為民、為安，故民安其處。</p><h3 id="乾之萃" tabindex="-1">乾之萃 <a class="header-anchor" href="#乾之萃" aria-label="Permalink to “乾之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>任劣力薄，孱駑恐怯。如蝟見鵲，不敢拒格。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>坤柔，故曰任劣。力薄曰孱駑，互大坎，故曰恐怯。巽為蝟，艮為鵲，坤弱，故不敢拒格。《史記龜策傳》註「蝟能制虎，見鵲則仰地。」○孱駑，依宋本。元刊作駑孱。</p><h3 id="乾之升" tabindex="-1">乾之升 <a class="header-anchor" href="#乾之升" aria-label="Permalink to “乾之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>衛侯東游，惑於少姬。亡我考妣，久迷不來。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>震為警衛、為諸侯、為東游。大坎為惑，兌為少姬。震為父，坤為母，故曰考妣，坤死，故亡，坤為我、為迷，震往故不來。衛文侯避國難，游齊。少姬，衛女，齊桓夫人。○震父象失傳。迷，依宋元本，汲古作逝。</p><h3 id="乾之困" tabindex="-1">乾之困 <a class="header-anchor" href="#乾之困" aria-label="Permalink to “乾之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>噂噂所言，莫如我垣。歡喜堅固，可以長安。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>《詩》：「噂沓背憎「箋雲「噂噂，對語，背則相憎。」困三至上，正反兩兌口相背，故易曰有言不信，其伏象則正反兩震言相對，故曰噂噂所言。巽為垣墉，坎陷，故莫如我垣。兌悅而伏艮，故曰歡喜堅固，曰長安。○如，俗本誤加。如者，往也，宋本、汲古本均不誤，元本作知。</p><h3 id="乾之井" tabindex="-1">乾之井 <a class="header-anchor" href="#乾之井" aria-label="Permalink to “乾之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>黿鳴岐山，鱉應幽淵。男女媾精，萬物化生。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>文王以成，為開周庭。通噬嗑。互艮為黿鱉、為山，下震兩岐，故曰岐山。而初至四正反艮震，震為鳴，故上鳴下應，與《中孚》九二「鳴鶴在陰，其子和之」用象同也。坎為幽，坎男離女，而坎為精，故曰男女媾精，震為萬物、為生、為王。上離為文，故曰文王以成。艮為成也，艮又為庭。震為周、為開，故曰為開周庭。○黿，依汲古，宋元本作鸑。幽淵，依宋元本，汲古作山淵。</p><h3 id="乾之革" tabindex="-1">乾之革 <a class="header-anchor" href="#乾之革" aria-label="Permalink to “乾之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>玄黃虺隤，行者勞罷。役夫憔悴，逾時不歸。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通蒙。互震為玄黃。《詩毛傳》「玄黃虺隤，病也。」蒙坎為病、為罷勞，震為行，故曰行者勞罷。坎為夫、為勞卦，故曰役夫憔悴。艮為時，在外，故逾時不歸。</p><h3 id="乾之鼎" tabindex="-1">乾之鼎 <a class="header-anchor" href="#乾之鼎" aria-label="Permalink to “乾之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>弱足刖跟，不利出門。市賈無利，折亡為患。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>下巽，震伏不見，故曰弱足刖跟，故不利出門，鼎初六「鼎，顛趾」即如是取象。三五伏艮，艮為門。巽為市賈、為利，兌折，故不利、故折亡，大坎為患。○利，汲古訛私，無，從元本，宋本作不。</p><h3 id="乾之震" tabindex="-1">乾之震 <a class="header-anchor" href="#乾之震" aria-label="Permalink to “乾之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>懸貆素餐，居非其官。失輿剝廬，休坐徙居。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>懸貆素餐，《詩伐檀》語也，互艮為貆，伏巽繩，故懸貆，震為食、為白，故曰素餐。艮為居、為官，艮覆，故居非其官。震為輿，坎失，故曰失輿。艮為廬，艮覆，故剝廬，「君子得輿，小人剝廬」，《剝》上九爻詞也。艮為坐、為居，艮覆，故休坐徙居。○官，依元本，宋本作安。徙，依元本，宋本作徒。餐，從宋本，元本訛饕。</p><h3 id="乾之艮" tabindex="-1">乾之艮 <a class="header-anchor" href="#乾之艮" aria-label="Permalink to “乾之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>民怯城惡，姦人所伏。寇賊大至，入我郛郭，妻子俘獲。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>《左傳》：「成九年楚伐莒，莒城惡，眾潰」。艮為城，坎為民、為怯、為陷，故曰民怯城惡。坎為伏、為姦，互震為人，故曰姦人所伏。坎為寇賊，艮為郛郭，伏巽為入，故曰入我郛郭。震為子，伏兌為妻，艮止，故曰妻子俘獲。○城，依宋元本，汲古訛伐。郛、俘，依宋元本，汲古作邦、系。</p><h3 id="乾之漸" tabindex="-1">乾之漸 <a class="header-anchor" href="#乾之漸" aria-label="Permalink to “乾之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>陽低頭，陰仰首，水為災，傷我寶，進不利，難生子。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>坎為首，坎伏故低，坎陽卦而在下，離陰卦在坎上，故曰陰仰首。坎為水災，震為玉、為寶，震覆，故傷。震為行、為子、為生，震覆，故不利、故難。○寶，從汲古，宋元作足。難生子，依宋元本，汲古作生其子，與《易》「婦孕不育」旨背。</p><h3 id="乾之歸妹" tabindex="-1">乾之歸妹 <a class="header-anchor" href="#乾之歸妹" aria-label="Permalink to “乾之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>背北相憎，心意不同，如火與金。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>兌伏艮，艮為背，坎為北、為憎、為心意，離為火，伏艮為金。《詩十月》篇「噂沓背憎。」○宋元本作艮辭，金讀略如京，與憎同協。</p><h3 id="乾之豐" tabindex="-1">乾之豐 <a class="header-anchor" href="#乾之豐" aria-label="Permalink to “乾之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>太微帝室，黃帝所值。藩屏周衛，不可得入，常安無患。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>離為星，故曰太微、曰帝室。帝室者，帝座，即紫垣也。震為帝，伏坎為宮室，故曰帝室。震為黃，故曰黃帝。黃帝，軒轅星也。震為叢木、為屏藩、為周、為衛，巽入巽伏，故不可入。○周，從宋元本，汲古作固，於卦象無著。值，從汲古，宋元皆作宜，不協。</p><h3 id="乾之旅" tabindex="-1">乾之旅 <a class="header-anchor" href="#乾之旅" aria-label="Permalink to “乾之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>繭慄犧牲，敬享鬼神。神嗜飲食，受福多孫。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>互巽，故曰繭，艮為果，故曰慄。離為牛，故曰犧牲。《禮》「祭天地之牛角繭慄」，言其色似之也，故曰繭慄犧牲。伏坎為鬼，震為神、為飲食，故曰神嗜飲食。艮為孫，坎眾，故多孫。</p><h3 id="乾之巽" tabindex="-1">乾之巽 <a class="header-anchor" href="#乾之巽" aria-label="Permalink to “乾之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>出門逢惡，為患為怨。更相擊刺，傷我手端。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>通震。互艮，故曰出門，坎為惡、為患、為怨，初至四反正艮，艮手，故更相擊刺，坎折，故傷手。○患，宋本作禍。此全用震象，故互坎患。</p><h3 id="乾之兌" tabindex="-1">乾之兌 <a class="header-anchor" href="#乾之兌" aria-label="Permalink to “乾之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>鷁飛中退，舉事不遂，宋人亂潰。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>《左傳》：「六鷁退飛，風也。」為宋襄公敗徵，故曰宋人亂潰。兌伏艮，艮為鷁，巽為退，互震為舉、為人，艮為宋。《說文》「架木為屋曰宋」，艮形似之，故林以艮為宋。○遂，宋本、汲古作進，依元本，韻葉象亦合。</p><h3 id="乾之渙" tabindex="-1">乾之渙 <a class="header-anchor" href="#乾之渙" aria-label="Permalink to “乾之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>跛踦相隨，日暮牛罷。陵遲後旅，失利亡雌。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>坎蹇，故曰跛踦，巽順故曰相隨。艮為日，坎為暮，故曰日暮，艮為牛，坎勞，故曰牛疲。巽為陵遲，震為後，故曰陵遲後旅。巽為利、為雌，坎失，故曰失利亡雌。</p><h3 id="乾之節" tabindex="-1">乾之節 <a class="header-anchor" href="#乾之節" aria-label="Permalink to “乾之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>龍角博顙，位至公卿。世祿久長，起動安寧。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>震為龍，艮為角，震為顙，龍角猶日角。博顙，大顙也，皆貴相。艮為位，震為公，坎為祿，艮為久長，故曰世祿久長。震為起、為動，艮為安，故曰起動安寧。○顙，宋元本作預，非，依汲古。</p><h3 id="乾之中孚" tabindex="-1">乾之中孚 <a class="header-anchor" href="#乾之中孚" aria-label="Permalink to “乾之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>舜升大禹，石夷之野。徵詣王庭，拜治水土。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>震為帝，故曰舜禹。艮為石、為野。按：《洛書靈準聽》曰「禹出石夷，掘地代，懷玉鬥。」石夷不見於他書，而《蜀志秦宓傳》雲「禹生石紐」，又譙周《蜀本紀》「禹本汶山廣柔縣人，生於石紐」，又《吳越春秋》「鯀娶女嬉，吞薏苡有感，剖脅而產高密，家於西羌，地曰石紐。」又《地理通釋》引皇甫謐曰「孟子稱禹生於石紐，西夷人也。」茲曰石夷，不知於石紐是否為一地，不能明也。震為王，艮為庭，震往，故曰徵詣王庭。艮手為拜，伏大坎，坎為水、為土，故曰拜治水土。此以坎為土，與邵子同。○拜，從元本，宋本作刊。</p><h3 id="乾之小過" tabindex="-1">乾之小過 <a class="header-anchor" href="#乾之小過" aria-label="Permalink to “乾之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>從風放火，荻芝俱死。三害集房，叔子中傷。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>巽為風，艮為火，巽艮連，故曰從風放火。巽為草莽、為荻芝，中爻互大過，大過死，故曰荻芝俱死。艮為房，數三，坎為害，在中爻，故曰三害集房。艮為叔子，兌毀，故中傷，以艮為火，邵子所本，三害暴虐頗也。見《左傳昭十四年》註。</p><h3 id="乾之既濟" tabindex="-1">乾之既濟 <a class="header-anchor" href="#乾之既濟" aria-label="Permalink to “乾之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>楩生荊山，命制輸班。袍衣剝脫，夏熱冬寒。饑餓枯槁，眾人莫憐。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>卦有三震形，故曰楩、曰荊，又有半艮，故曰山，又有半巽，巽為命、為工、為輸班。坎為制，故命制輸班。震為襦，故曰袍衣，三震上下往複，如剝脫然，言上六之初即成未濟也，坎冬寒，離夏熱。離虛為饑餓、為枯槁，坎為眾，震為笑樂，故曰莫憐。○眾人莫憐，宋本作莫人莫憐，宋本作莫人莫憐，元本作莫人震憐，皆不適，故從汲古。楩，宋元、汲古皆作梗，依局本。</p><h3 id="乾之未濟" tabindex="-1">乾之未濟 <a class="header-anchor" href="#乾之未濟" aria-label="Permalink to “乾之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>長面大鼻，來解己憂。遺吾福子，惠我嘉喜。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>艮為鼻、為面，三艮形故曰長面大鼻。坎為憂，震為解、為福、為子、為嘉喜，此與上卦皆用半象，本之《易》也。○宋元本福子下多「與我惠妻」四字。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
